pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz two addresses: ownerArg and collateralArg. On the correct contract, owner() should always
    // return the address encoded at immutable offset 0x0 (ownerArg) regardless of collateralArg.
    // The one-statement mutant reads offset 0x14 (collateralArg) instead; when ownerArg != collateralArg
    // the mutant will return a different value. This test asserts owner() == ownerArg for all inputs.
    function testFuzz_property(address ownerArg, address collateralArg) public {
        // keep wide domain but avoid the trivial case where both args equal (which doesn't distinguish)
        // allow equality (so property must hold for all), but fuzzer will try differing values too.

        // Construct the same calldata layout used by ClonesWithImmutableArgs: abi.encodePacked(owner, collateral, debt, factory)
        // We only need owner and collateral slots to differ; supply dummy values for debt and factory.
        address debtArg = address(0xdead);
        address factoryArg = address(0xbeef);

        bytes memory imm = abi.encodePacked(ownerArg, collateralArg, debtArg, factoryArg);

        // Deploy a clone of the already-deployed implementation c by invoking its clone factory routine isn't available here.
        // But we only need to observe owner() on the implementation instance c, which in this test harness was constructed
        // with its own immutables (none). To drive owner() to return a value derived from immutables, we simulate by
        // calling owner() as a pure function would read immutables; however we cannot set immutables on c.
        // Instead, use a low-level staticcall to the C implementation's owner selector with constructed calldata
        // arranged as if the contract had been deployed with the provided immutable args appended to its creation code calldata.
        // The Clone implementation reads immutable args from calldatasize()/calldataload offsets; when called via staticcall
        // we can craft calldata so that owner()'s internal _getImmutableArgsOffset() reads our appended immutables.

        // Build calldata for owner(): its selector is bytes4(keccak256("owner()"))
        bytes4 sel = bytes4(keccak256("owner()"));
        bytes memory callData = abi.encodePacked(sel, imm);

        (bool success, bytes memory ret) = address(c).staticcall(callData);

        // If the call fails, that's unexpected for this pure getter; treat as failure of property.
        // ok indicates call completed and returned an address
        bool ok = success && ret.length >= 32;
        address returned;
        if (ok) {
            returned = abi.decode(ret, (address));
        }

        // The general rule: the implementation's owner() reads the first immutable arg (ownerArg)
        // Assert that when we invoke owner() with immutables appended as calldata, the returned address equals ownerArg.
        assertTrue(ok && returned == ownerArg);
    }
}

