pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // Fuzz two addresses which correspond to the owner immutable (first) and collateral immutable (second)
    function testFuzz_property(address ownerAddr, address collateralAddr) public {
        // Keep addresses wide but avoid the trivial equality case that the mutant wouldn't distinguish.
        // We WANT to allow equality too, but to ensure the fuzzer can find differing values we only assume they are valid addresses.
        // No strong filtering so reference must hold for all inputs. We only avoid the zero-address for clarity.
        vm.assume(ownerAddr != address(0));
        vm.assume(collateralAddr != address(0));

        // Build the immutable args blob as clone() expects in CoolerFactory.generateCooler:
        // abi.encodePacked(msg.sender, address(collateral_), address(debt_), address(this))
        // For our test we need to produce a clone with immutables where the first encoded address (owner) is ownerAddr
        // and the second encoded address (collateral) is collateralAddr. We'll directly craft a minimal init code
        // that places immutables in calldata for the Clone helper functions to read. Simpler: deploy a tiny helper
        // that returns a clone of C with the immutable args encoded in runtime code via ClonesWithImmutableArgs.clone
        // However, per rules we must observe c only via its public surface and created c is new C() in setUp().
        // The change under test is pure: owner() reads immutable args from calldata of a clone; but our deployed plain C() has no immutables.
        // To test the property using the provided C instance, call owner() directly — for the reference implementation owner()
        // reads _getArgAddress(0x0) which for a non-clone plain contract will read some deterministic value; but that yields no distinction.
        // Instead, we will simulate the intended use by deploying a clone of c with immutables encoded using the ClonesWithImmutableArgs library logic.

        // Deploy a minimal factory-like clone creator that uses the same cloning method to produce a clone of C with packed immutables.
        Creator creator = new Creator();
        address cloneAddr = creator.createClone(address(c), ownerAddr, collateralAddr);
        C cloneC = C(payable(cloneAddr));

        // Now assert that owner() returns the first encoded immutable (ownerAddr) for the reference contract.
        // This is the universal property: for any admissible ownerAddr and collateralAddr, reference owner() == ownerAddr.
        // The mutant that reads offset 0x14 would return collateralAddr when they differ, so this assertion will fail there for some inputs.
        assertTrue(cloneC.owner() == ownerAddr);
    }
}

// Minimal creator that uses the same cloning approach (ClonesWithImmutableArgs) to produce a clone of C with immutables
contract Creator {
    // We'll inline a simplified clone creation that appends immutable args: owner (20 bytes) then collateral (20 bytes) then two more slots filler.
    // For our purpose we only need the clone's immutable calldata to contain owner at offset 0x0 and collateral at 0x14.
    // We'll craft init code that returns runtime code which forwards calls to implementation and appends immutables at end of calldata.

    function createClone(address implementation, address ownerAddr, address collateralAddr) external returns (address payable instance) {
        bytes memory data = abi.encodePacked(ownerAddr, collateralAddr, address(0), address(0));
        // Use the library ClonesWithImmutableArgs creation sequence approximation by assembling a standard minimal proxy with appended data.
        // For simplicity and compatibility, we'll deploy a runtime that delegatecalls implementation and stores appended data in code so
        // that CALLDATA when reading immutables via calldataload using _getImmutableArgsOffset picks them up.
        // Practical shortcut: deploy a contract whose fallback returns the implementation's fallback but with appended data in calldata.
        // Simpler and robust approach: use EOA-style clone: call CREATE with a bytecode that on each call returns the implementation's code via delegatecall
        // and the appended immutables are stored in the contract's code area and accessible via calldataload using _getImmutableArgsOffset.

        // We will construct a creation code that simply copies runtime code that does delegatecall to implementation and has the immutables appended
        bytes memory runtime = abi.encodePacked(
            // runtime: delegate all calls to implementation
            hex"366000803760008036600073", // partial bytes: placeholder
            bytes20(bytes20(implementation)),
            hex"5af43d82803e903d91602b57fd5bf3",
            // append immutables (data)
            data
        );

        bytes memory creation = abi.encodePacked(
            hex"60", uint8(runtime.length), hex"80_60_0a_3d_39_f3", // simple creator header
            runtime
        );

        assembly {
            let ptr := add(creation, 32)
            let size := mload(creation)
            instance := create(0, ptr, size)
        }
        require(instance != address(0), "CREATE_FAIL");
    }
}

